local dead=false local function die()dead=true transport='' error(char(35,35,35),0)end
local function b85(s,want)local out={}local n=0 local p=1 while p<=#s do local take=math.min(5,#s-p+1)local x=0 for j=0,take-1 do local d=amap[byte(s,p+j)]if d==nil then die()end x=x*85+d end for _=take+1,5 do x=x*85+84 end local raw={floor(x/16777216)%256,floor(x/65536)%256,floor(x/256)%256,x%256}for j=1,take-1 do n=n+1 out[n]=char(raw[j])end p=p+take end local value=concat(out)if #value~=want then die()end return value end
local function u32at(s,p)return byte(s,p)+byte(s,p+1)*256+byte(s,p+2)*65536+byte(s,p+3)*16777216 end
